:root {
  --bg: #fffaf2;
  --border: #d4a35a;
  --header-bg: #f5c96a;
  --title-color: #5a3a0a;
  --latin-color: #8a6030;
  --status-bg: #3a7d44;
  --status-text: #ffffff;
  --label-color: #a06820;
  --value-color: #3d2800;
  --divider: #e8c98a;
}

.mushroom-tag {
  background: var(--bg);
  border: 2px solid var(--border);
  border-radius: 14px;
  width: 320px;
  overflow: hidden;
  font-size: 14px;
}

.tag-header {
  background: var(--header-bg);
  display: flex;
  align-items: center;
  gap: 10px;
  padding: 12px 16px;
}

.tag-icon {
  font-size: 32px;
  line-height: 1;
}

.tag-title-group {
  display: flex;
  flex-direction: column;
  gap: 2px;
  flex: 1;
}

.tag-title {
  font-size: 20px;
  font-weight: 700;
  color: var(--title-color);
  margin: 0;
  line-height: 1.1;
}

.tag-latin {
  font-size: 12px;
  color: var(--latin-color);
  font-style: italic;
}

.tag-status {
  background: var(--status-bg);
  color: var(--status-text);
  font-size: 11px;
  font-weight: 700;
  padding: 4px 10px;
  border-radius: 20px;
  letter-spacing: 0.5px;
  text-transform: uppercase;
  align-self: flex-start;
}

.tag-body {
  padding: 12px 16px;
}

.tag-details {
  list-style: none;
  margin: 0;
  padding: 0;
  display: flex;
  flex-direction: column;
  gap: 0;
}

.tag-details li {
  display: flex;
  justify-content: space-between;
  align-items: center;
  padding: 8px 0;
  border-bottom: 1px solid var(--divider);
}

.tag-details li:last-child {
  border-bottom: none;
}

.detail-label {
  font-weight: 600;
  color: var(--label-color);
  font-size: 13px;
  text-transform: uppercase;
  letter-spacing: 0.4px;
}

.detail-value {
  color: var(--value-color);
  font-size: 13px;
}
